R=C=20
g=[[0]*C for _ in range(R)]
# Base rectangle
for r in range(2,9):
    for c in range(9,16): g[r][c]=2
# marker points
pts=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
# extend horizontal across rows of the rectangle, on sides opposite any marker
for r in range(2,9):
    left=any(rr==r and cc<9 for rr,cc in pts)
    right=any(rr==r and cc>15 for rr,cc in pts)
    if left and not right:
        for c in range(9,20): g[r][c]=2
    elif right and not left:
        for c in range(0,16): g[r][c]=2
    else:
        for c in range(C): g[r][c]=2
# vertical extension across columns in rectangle, suppressing side with markers
for c in range(9,16):
    top=any(cc==c and rr<2 for rr,cc in pts)
    bottom=any(cc==c and rr>8 for rr,cc in pts)
    if top and not bottom:
        for r in range(2,20): g[r][c]=2
    elif bottom and not top:
        for r in range(0,9): g[r][c]=2
    else:
        for r in range(R): g[r][c]=2
for r,c in pts: g[r][c]=1
print(g)
